import 'dart:ui' show Rect, DisplayFeatureType;
import 'package:flutter/material.dart';

void main() => runApp(const AdaptiveNotebook());

class AdaptiveNotebook extends StatelessWidget {
  const AdaptiveNotebook({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'Adaptive notebook starter',
    themeAnimationDuration: Duration.zero,
    theme: ThemeData(
      useMaterial3: true,
      colorScheme: const ColorScheme.light(
        primary: Color(0xff244f61), onPrimary: Colors.white,
        secondary: Color(0xff445c35), onSecondary: Colors.white,
        surface: Color(0xfff5f4ee), onSurface: Color(0xff1e3037),
        error: Color(0xffa0202b), onError: Colors.white,
      ),
      scaffoldBackgroundColor: const Color(0xfff5f4ee),
      visualDensity: VisualDensity.standard,
    ),
    home: const NotebookDashboard(),
  );
}

class NotebookDashboard extends StatefulWidget {
  const NotebookDashboard({super.key});
  @override
  State<NotebookDashboard> createState() => _NotebookDashboardState();
}

class _NotebookDashboardState extends State<NotebookDashboard> {
  int selected = 0;
  static const names = ['Drafting', 'Review', 'Ready'];
  static const descriptions = [
    'Describe the first useful action before moving the item into review.',
    'Read for missing context, unresolved decisions, and an understandable next step.',
    'These sample items are ready for a handoff, not a production release.',
  ];
  static const counts = [14, 8, 6];

  Widget heading(String text) => Semantics(
    header: true,
    child: Text(text, style: Theme.of(context).textTheme.headlineSmall),
  );

  Widget overview() => Padding(
    padding: const EdgeInsets.all(24),
    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      const Text('NOTEBOOK / SAMPLE OPERATIONS'),
      const SizedBox(height: 16),
      heading('Work at a glance'),
      const SizedBox(height: 12),
      const Text('28 fictional items. Select a queue to inspect its sample handoff notes. No live service is connected.'),
      const SizedBox(height: 24),
      for (int i = 0; i < names.length; i++) ...[
        Semantics(
          selected: selected == i,
          child: OutlinedButton(
            style: OutlinedButton.styleFrom(
              minimumSize: const Size(0, 48),
              padding: const EdgeInsets.all(16),
              backgroundColor: selected == i ? const Color(0xffe2e9eb) : null,
              side: BorderSide(color: selected == i ? const Color(0xff244f61) : const Color(0xff738891)),
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(4)),
            ),
            onPressed: () => setState(() => selected = i),
            child: Align(alignment: Alignment.centerLeft, child: Text('${names[i]} — ${counts[i]} items')),
          ),
        ),
        const SizedBox(height: 12),
      ],
      const SizedBox(height: 12),
      const Text('Read-only starter: selections are local and reset when this app closes.'),
    ]),
  );

  Widget detail() => Padding(
    padding: const EdgeInsets.all(24),
    child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Semantics(liveRegion: true, header: true, child: Text('${names[selected]} queue', style: Theme.of(context).textTheme.headlineSmall)),
      const SizedBox(height: 12),
      Text(descriptions[selected]),
      const SizedBox(height: 24),
      heading('Example handoff'),
      const SizedBox(height: 16),
      const Divider(color: Color(0xff738891)),
      const SizedBox(height: 12),
      const Text('Item 01 / Clarify the outline', style: TextStyle(fontWeight: FontWeight.w700)),
      const SizedBox(height: 8),
      const Text('Add one sentence explaining the intended reader. Keep unanswered questions beside the draft.'),
      const SizedBox(height: 20),
      const Divider(color: Color(0xff738891)),
      const SizedBox(height: 12),
      const Text('Item 02 / Record a decision', style: TextStyle(fontWeight: FontWeight.w700)),
      const SizedBox(height: 8),
      const Text('Describe the option chosen and why. This is fictional workflow copy, not a claim about team performance.'),
      const SizedBox(height: 24),
      const Text('Accessibility note: color is supplementary; queue labels and counts carry the information.'),
    ]),
  );

  Widget scrollPane(Widget child, String label) => Semantics(
    container: true, label: label,
    child: SingleChildScrollView(child: child),
  );

  Widget ordinary(double width) {
    if (width >= 800) {
      return Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Expanded(flex: 2, child: scrollPane(overview(), 'Queue navigation')),
        const VerticalDivider(width: 1, color: Color(0xff738891)),
        Expanded(flex: 3, child: scrollPane(detail(), 'Selected queue detail')),
      ]);
    }
    return SingleChildScrollView(child: Column(children: [overview(), const Divider(color: Color(0xff738891)), detail()]));
  }

  @override
  Widget build(BuildContext context) {
    final media = MediaQuery.of(context);
    return Scaffold(body: SafeArea(child: FocusTraversalGroup(
      policy: ReadingOrderTraversalPolicy(),
      child: LayoutBuilder(builder: (context, constraints) {
        final width = constraints.maxWidth;
        final height = constraints.maxHeight;
        List<Rect>? regions;
        // Display-feature bounds are in screen coordinates; SafeArea shifts this body.
        for (final feature in media.displayFeatures) {
          if (feature.type != DisplayFeatureType.hinge && feature.type != DisplayFeatureType.fold) continue;
          final b = feature.bounds.shift(Offset(-media.padding.left, -media.padding.top));
          if (b.height >= height * .8 && b.left > 0 && b.right < width) {
            regions = [Rect.fromLTRB(0, 0, b.left, height), Rect.fromLTRB(b.right, 0, width, height)];
            break;
          }
          if (b.width >= width * .8 && b.top > 0 && b.bottom < height) {
            regions = [Rect.fromLTRB(0, 0, width, b.top), Rect.fromLTRB(0, b.bottom, width, height)];
            break;
          }
        }
        if (regions == null) return ordinary(width);
        final panes = regions;
        if (panes.every((r) => r.width >= 260 && r.height >= 180)) {
          return Stack(children: [
            Positioned.fromRect(rect: panes[0], child: scrollPane(overview(), 'First foldable pane: queues')),
            Positioned.fromRect(rect: panes[1], child: scrollPane(detail(), 'Second foldable pane: details')),
          ]);
        }
        // If a pane is too narrow, keep the entire flow on the larger usable side.
        final largest = panes.reduce((a, b) => a.width * a.height >= b.width * b.height ? a : b);
        return Stack(children: [Positioned.fromRect(rect: largest, child: ordinary(largest.width))]);
      }),
    )));
  }
}
